import{_ as t,o as r,c as a,a0 as o}from"./chunks/framework.DScjKhBS.js";const m=JSON.parse('{"title":"nWave vs Superpowers — Executive summary","description":"One-page leadership brief and decision matrix for nWave and Superpowers.","frontmatter":{"layout":"doc","title":"nWave vs Superpowers — Executive summary","description":"One-page leadership brief and decision matrix for nWave and Superpowers."},"headers":[],"relativePath":"reports/agentic-framework-comparison/00-executive-summary.md","filePath":"reports/agentic-framework-comparison/00-executive-summary.md"}'),n={name:"reports/agentic-framework-comparison/00-executive-summary.md"};function s(i,e,d,l,c,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="nwave-vs-superpowers-executive-summary" tabindex="-1">nWave vs Superpowers: Executive summary <a class="header-anchor" href="#nwave-vs-superpowers-executive-summary" aria-label="Permalink to &quot;nWave vs Superpowers: Executive summary&quot;">​</a></h1><p><strong>Purpose:</strong> A one-page view for product and engineering leaders choosing an agentic development posture. For depth, see the <a href="./reports/agentic-framework-comparison/">full research</a>.</p><h2 id="the-decision-in-one-sentence" tabindex="-1">The decision in one sentence <a class="header-anchor" href="#the-decision-in-one-sentence" aria-label="Permalink to &quot;The decision in one sentence&quot;">​</a></h2><p><strong>nWave</strong> standardises a gated, auditable <strong>seven-wave pipeline</strong> with <strong>runtime enforcement</strong> (hooks, TDD and edit discipline). <strong>Superpowers</strong> standardises <strong>reusable skills</strong> and a <strong>plan–implement–review</strong> lifecycle with <strong>broad tool portability</strong> and <strong>instruction-based</strong> discipline.</p><h2 id="decision-matrix-leadership" tabindex="-1">Decision matrix (leadership) <a class="header-anchor" href="#decision-matrix-leadership" aria-label="Permalink to &quot;Decision matrix (leadership)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>nWave</th><th>Superpowers</th></tr></thead><tbody><tr><td><strong>Primary control</strong></td><td>Process gates + hook enforcement (DES)</td><td>Skills (<code>SKILL.md</code>) + mandatory workflows when applicable</td></tr><tr><td><strong>Shape of work</strong></td><td>Fixed waves (discover → … → deliver)</td><td>Composable skills (brainstorm, worktrees, plans, TDD, review, finish)</td></tr><tr><td><strong>Human approval</strong></td><td>Explicit per-wave review before continuing</td><td>Design sign-off, checkpoints, subagent review loops</td></tr><tr><td><strong>Portability</strong></td><td>Best with Claude Code + CLI; plugin-only path is degraded for enforcement</td><td>Documented for Claude, Codex, Cursor, Gemini, OpenCode, Copilot, etc.</td></tr><tr><td><strong>Quality vs cost</strong></td><td><strong>Rigor profiles</strong> (lean → exhaustive) trade depth for tokens</td><td>Tuned by which skills you adopt and how strictly teams follow them</td></tr><tr><td><strong>Governance / audit</strong></td><td>Strong artifact trail + enforcement messages</td><td>Strong when skills are versioned and reviewed; less “hard” blocking by default</td></tr><tr><td><strong>Team overhead</strong></td><td>Higher ceremony; best when predictability &amp; compliance offset cost</td><td>Lower friction to start; best when you can govern skills as internal product</td></tr></tbody></table><p><em>Sources: <a href="https://github.com/nWave-ai/nWave" target="_blank" rel="noreferrer">nWave README</a>, <a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">Superpowers README</a>, <a href="https://blog.fsck.com/2025/10/09/superpowers/" target="_blank" rel="noreferrer">Superpowers launch</a>.</em></p><h2 id="when-to-shortlist-each" tabindex="-1">When to shortlist each <a class="header-anchor" href="#when-to-shortlist-each" aria-label="Permalink to &quot;When to shortlist each&quot;">​</a></h2><p><strong>Favour nWave</strong> if you need: repeatable SDLC handoffs, hard-to-bypass TDD/phase rules, clear audit narrative, and are willing to invest in the pipeline and Claude Code + CLI setup.</p><p><strong>Favour Superpowers</strong> if you need: the same <em>ideas</em> (plan, TDD, review) across many agent products, fast rollout, and incremental adoption—accepting that consistency depends on discipline and skill maintenance more than on hooks.</p><h2 id="risks-to-flag-in-steering-committees" tabindex="-1">Risks to flag in steering committees <a class="header-anchor" href="#risks-to-flag-in-steering-committees" aria-label="Permalink to &quot;Risks to flag in steering committees&quot;">​</a></h2><ul><li><strong>nWave:</strong> Process drag on small changes; enforcement tied to install path; team training on waves and DES behaviour.</li><li><strong>Superpowers:</strong> Compliance variance across teams/models; skill debt and conflicting guidance if not owned like internal docs.</li></ul><h2 id="suggested-next-step-1–2-weeks" tabindex="-1">Suggested next step (1–2 weeks) <a class="header-anchor" href="#suggested-next-step-1–2-weeks" aria-label="Permalink to &quot;Suggested next step (1–2 weeks)&quot;">​</a></h2><ol><li><strong>Pilot one real feature</strong> in each model (or nWave in one squad, Superpowers in another) with the same success criteria: defects escaped, time-to-merge, and engineer satisfaction.</li><li><strong>Name an owner</strong> for method maintenance (nWave: pipeline/rigor; Superpowers: skill library and reviews).</li><li>Revisit the <a href="./reports/agentic-framework-comparison/">full comparison</a> if you need negotiation-level detail (differences, pros/cons, references).</li></ol><hr><p><a href="./reports/agentic-framework-comparison/">← Full research: nWave vs Superpowers</a></p>',16)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
